.magnetic-btn {
  padding: 15px 30px;
  font-size: 16px;
  font-weight: bold;
  color: #fff;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 30px;
  cursor: pointer;
  transition: transform 0.2s ease-out, box-shadow 0.3s ease, background 0.3s ease;
  backdrop-filter: blur(10px);
}
.magnetic-btn:hover, .magnetic-btn:active {
  box-shadow: 0 0 20px #00d2ff, inset 0 0 10px #00d2ff;
  border-color: #00d2ff;
  background: rgba(0, 210, 255, 0.1);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;perspective:1000px;';

const btn = document.createElement('button');
btn.className = 'magnetic-btn';
btn.innerText = 'PULL ME';
c.appendChild(btn);

btn.addEventListener('pointermove', (e) => {
  const rect = btn.getBoundingClientRect();
  const x = e.clientX - rect.left - rect.width / 2;
  const y = e.clientY - rect.top - rect.height / 2;
  btn.style.transform = `translate(${x * 0.4}px, ${y * 0.4}px)`;
});

btn.addEventListener('pointerleave', () => {
  btn.style.transform = 'translate(0px, 0px)';
});
btn.addEventListener('pointerup', () => {
  btn.style.transform = 'translate(0px, 0px)';
});
